/**
 * Article metadata for client components (spec 34 §17.10): slugs, titles, intros and domain proverbs,
 * without the article bodies (those come from the server as props). Generated by
 * scripts/articles/check.ts --write; check:articles keeps it in step with content/articles.
 */
import data from './manifest.json';
import type { DomainManifest, Manifest, TopicMeta } from './types';

const manifest = data as Manifest;

export type CultureDomain = DomainManifest;
export type Topic = TopicMeta;

export const domains: DomainManifest[] = manifest.culture;
export const historyDomain: DomainManifest = manifest.history;
export const oralTraditionsDomain: DomainManifest = manifest.language;

export function getDomain(slug: string) {
  return domains.find((d) => d.slug === slug);
}

export function getTopic(domainSlug: string, topicSlug: string) {
  const domain = getDomain(domainSlug);
  const topic = domain?.topics.find((t) => t.slug === topicSlug);
  return domain && topic ? { domain, topic } : null;
}

export function getHistoryTopic(topicSlug: string) {
  const topic = historyDomain.topics.find((t) => t.slug === topicSlug);
  return topic ? { domain: historyDomain, topic } : null;
}

export function getLanguageTopic(topicSlug: string) {
  const topic = oralTraditionsDomain.topics.find((t) => t.slug === topicSlug);
  return topic ? { domain: oralTraditionsDomain, topic } : null;
}
